/**
 * Local, deterministic mock conversation for the Living Office chat (Phase 1.1).
 *
 * Every line here is a predefined template; nothing is generated by a model and nothing leaves
 * the browser. A message is classified with a few keyword rules into small talk, a status
 * question or a task request; task requests become a proposal the user confirms, and the work
 * then runs on the office simulation as a clearly labelled demo.
 */
import type { AgentId } from "./agents";

export type TaskCategory = "code" | "test" | "research" | "ops" | "report" | "team" | "general";

export interface TaskProposal {
  title: string;
  description: string;
  category: TaskCategory;
}

export interface QuickTask {
  id: string;
  label: string;
  title: string;
  category: TaskCategory;
}

export const MAX_MESSAGE_LENGTH = 280;
const MAX_TITLE_LENGTH = 60;

