/** What each role does with a task, in the agent's own words. */
const ROLE_PLAN: Record<AgentId, string> = {
  commander: "split it across the team and collect the results",
  coder: "work on it at my desk",
  researcher: "dig into it in the Research Corner",
  tester: "run it in the test bay",
  ops: "check it at the Ops Wall",
  reporter: "put it together in the Reporting Area",
  worker1: "work on it at my desk",
  worker2: "work on it at my desk",
};

/** The category a role's own work falls into (used when a request names none). */
export const ROLE_CATEGORY: Record<AgentId, TaskCategory> = {
  commander: "team", coder: "code", researcher: "research", tester: "test", ops: "ops", reporter: "report", worker1: "code", worker2: "code",
};

const CATEGORY_WORDS: [TaskCategory, RegExp][] = [
  ["test", /\b(test|tests|testing|qa|verify|validate|check(s|ing)?\b(?!.*\b(health|system|server|alert)))/],
  ["ops", /\b(health|uptime|server|servers|system|systems|alert|alerts|incident|monitor|monitoring|deploy|infra|latency|outage|logs?)\b/],
  ["research", /\b(research|investigate|explore|compare|trend|trends|study|analy[sz]e|look into|find out|learn)\b/],
  ["report", /\b(report|summar(y|ise|ize)|present|presentation|recap|digest|update the team|brief)\b/],
  ["code", /\b(build|fix|implement|code|coding|feature|bug|refactor|write|ship|develop|program|api|endpoint|page)\b/],
  ["team", /\b(team|everyone|plan|coordinate|delegate|organi[sz]e)\b/],
];

/** Keyword category of a request ("general" when nothing matches). */
export function classify(text: string): TaskCategory {
  const t = text.toLowerCase();
  for (const [cat, re] of CATEGORY_WORDS) if (re.test(t)) return cat;
  return "general";
}

const POLITE_PREFIX = /^(hey|hi|hello|ok(ay)?|so|please|pls|can you|could you|would you|will you|i need you to|i want you to|i'd like you to|i would like you to|go ahead and|let's|lets|you should|try to)\b[\s,]*/i;

/** A short task title from a request: polite lead-ins and trailing punctuation removed, first letter capitalised. */
export function taskTitle(text: string): string {
  let t = text.replace(/\s+/g, " ").trim();
  for (let i = 0; i < 4; i++) {
    const next = t.replace(POLITE_PREFIX, "").trim();
    if (next === t) break;
    t = next;
  }
  for (let i = 0; i < 3; i++) t = t.replace(/[\s.!?,;:]+$/, "").replace(/\s*\b(please|for me|thanks|thank you)$/i, "");
  t = t.trim();
  if (!t) return "";
  if (t.length > MAX_TITLE_LENGTH) t = `${t.slice(0, MAX_TITLE_LENGTH - 1).replace(/\s+\S*$/, "")}…`;
  return t[0].toUpperCase() + t.slice(1);
}

export type MessageCheck = { ok: true; text: string } | { ok: false; reason: "empty" | "too_long" };

export function checkMessage(raw: string): MessageCheck {
  const text = raw.replace(/\r\n?/g, "\n").trim();
  if (!text) return { ok: false, reason: "empty" };
  if (text.length > MAX_MESSAGE_LENGTH) return { ok: false, reason: "too_long" };
  return { ok: true, text };
}

export interface ChatContext {
  agent: AgentId;
  name: string;
  /** What the agent is doing now (its status label or detail). */
  doing: string;
  /** Title of the user task it is working on, if any. */
  activeTask: string | null;
  queued: number;
}

export type Interpretation =
  | { kind: "reply"; text: string }
  | { kind: "proposal"; text: string; proposal: TaskProposal };

/** The agent's answer to a free-text message. Pure: the same text and context give the same answer. */
export function interpret(raw: string, ctx: ChatContext): Interpretation {
  const text = raw.trim();
  const t = text.toLowerCase();
  const words = t.split(/\s+/).filter(Boolean);
  if (/^(hi|hello|hey|hiya|yo|good (morning|afternoon|evening))\b/.test(t) && words.length <= 4) {
    return { kind: "reply", text: `Hi! I'm ${ctx.name}. Tell me a task and I'll ${ROLE_PLAN[ctx.agent]} — as a demo simulation.` };
  }
  if (/\b(thanks|thank you|thx|cheers)\b/.test(t) && words.length <= 6) {
    return { kind: "reply", text: "Happy to help!" };
  }
  if (/\b(status|progress|what are you (doing|working on)|how('s| is) it going|are you busy)\b/.test(t)) {
    const queue = ctx.queued ? ` ${ctx.queued} more ${ctx.queued === 1 ? "task is" : "tasks are"} queued.` : "";
    return {
      kind: "reply",
      text: ctx.activeTask ? `I'm working on “${ctx.activeTask}” (demo).${queue}` : `Right now: ${ctx.doing.toLowerCase()}. No task from you yet.${queue}`,
    };
  }
  if (/\b(help|what can you do|who are you)\b/.test(t)) {
    return { kind: "reply", text: `I can take a task and ${ROLE_PLAN[ctx.agent]}. Try one of the suggestions below, or describe a task. Everything here is simulated.` };
  }
  if (/<[a-z/!][^>]*>/i.test(text) || /\b(javascript|onerror|onload)\s*[:=]/i.test(text)) {
    return { kind: "reply", text: "That looks like code or markup. I only take plain-language tasks here; could you describe it in words?" };
  }
  if (/\b(cancel|stop|abort)\b/.test(t) && words.length <= 4) {
    return { kind: "reply", text: "Tasks can't be cancelled from chat in this demo. You can replace my current task with a new one, or reset the demo." };
  }
  const title = taskTitle(text);
  const letters = (title.match(/[a-z]/gi) ?? []).length;
  if (!title || letters < 4 || (words.length < 2 && letters < 8)) {
    return { kind: "reply", text: "Could you tell me a bit more? For example: “Check the login flow.”" };
  }
  const category = classify(text);
  const proposal: TaskProposal = { title, description: text, category };
  const lead = ctx.activeTask
    ? `I'm on “${ctx.activeTask}” right now. I can queue “${title}” next, or switch to it now.`
    : `I can add a simulated task: “${title}”. I'll ${ROLE_PLAN[ctx.agent]} and report the result.`;
  return { kind: "proposal", text: lead, proposal };
}

/** Acknowledgement once a task is assigned (queued or started). */
export function ackMessage(title: string, queuedBehind: number): string {
  return queuedBehind > 0
    ? `Queued “${title}”. ${queuedBehind === 1 ? "One task is" : `${queuedBehind} tasks are`} ahead of it. I'll report back here (demo).`
    : `On it: “${title}”. I'll report back here when the demo task is done.`;
}

/** The simulated result, always labelled as a demo: no real work happened. */
export function resultMessage(category: TaskCategory, title: string, helpers?: string[]): string {
  switch (category) {
    case "code": return `Demo task completed: “${title}”. This was a simulation — no real code or files were changed.`;
    case "test": return `Simulated check completed: “${title}”. No real test suite was executed.`;
    case "research": return `Demo research completed: “${title}”. Simulated only — no live sources were read.`;
    case "ops": return `Demo system check completed: “${title}”. Simulated only — no real systems were inspected.`;
    case "report": return `Demo report is ready: “${title}”. It's a simulated summary — no real data was used.`;
    case "team": return `Team demo task completed: “${title}”.${helpers?.length ? ` ${helpers.join(" and ")} each finished a simulated part.` : ""} No real work was done.`;
    default: return `Demo task completed: “${title}”. This was a simulation only.`;
  }
}

/** Two agents a team task is split across (never the Commander itself). */
export function delegatesFor(category: TaskCategory): [AgentId, AgentId] {
  switch (category) {
    case "code": return ["coder", "tester"];
    case "test": return ["tester", "coder"];
    case "research": return ["researcher", "reporter"];
    case "report": return ["reporter", "researcher"];
    case "ops": return ["ops", "tester"];
    default: return ["researcher", "coder"];
  }
}
